        AND o.status = #{status}
    
    
        AND o.pay_status = #{payStatus}
    
    
        AND o.item_type = #{itemType}
    
    
        AND o.service_mode = #{serviceMode}
    
    
        AND (o.pet_name like concat('%', #{petName}, '%')
