             or o.contact_phone like concat('%', #{petName}, '%')
             or o.service_no like concat('%', #{petName}, '%'))
    
    
        AND date(o.appoint_time) = #{queryDate}
    

order by (date(o.appoint_time) = curdate()) desc,
         (case o.status when '0' then 0 when '1' then 1 when '2' then 2 else 9 end),
         o.appoint_time asc, o.service_id desc

