update pet_service_order
item_id = #{itemId}, item_name = #{itemName}, item_type = #{itemType}, service_mode = #{serviceMode}, contact_name = #{contactName}, contact_phone = #{contactPhone}, address = #{address}, price = #{price}, qty = #{qty}, total_amount = #{totalAmount}, staff_id = #{staffId}, staff_name = #{staffName}, appoint_time = #{appointTime}, start_time = #{startTime}, finish_time = #{finishTime}, status = #{status}, pay_status = #{payStatus}, pay_method = #{payMethod}, pay_time = #{payTime}, cancel_reason = #{cancelReason}, score = #{score}, comment = #{comment}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
