select status as status, count(*) as cnt
from pet_service_order
where del_flag = '0'
and store_id = #{storeId}
and date(appoint_time) = #{date}
group by status

select ifnull(sum(price), 0)
from pet_service_order
where del_flag = '0' and status = '3'
and store_id = #{storeId}
and date(finish_time) = #{date}
